// Kotlin bindings (UniFFI) + JNI libraries for crates/guardedsleep-ffi.
// Generated by `scripts/core-build.sh android`; both outputs are gitignored.
plugins {
    id("guardedsleep.android-library")
}

android {
    namespace = "org.guardedsleep.core"

    testOptions {
        unitTests.all {
            // Golden vectors shared with the Rust and WASM test suites.
            it.systemProperty(
                "conformance.vectors",
                rootProject
                    .file("../../crates/guardedsleep-core/vectors/conformance.json")
                    .absolutePath,
            )
            // gs-trace/1 documents replayed through the binding (ADR-016, AC-9).
            it.systemProperty(
                "conformance.traces",
                rootProject.file("../../crates/guardedsleep-core/vectors/traces").absolutePath,
            )
            // JVM unit tests need only a host build, no cross-compiled ABIs:
            //   - host library: <repo>/target/debug/libguardedsleep_ffi.so, built with
            //     `cargo build -p guardedsleep-ffi` (unstripped);
            //   - Kotlin bindings: apps/android/core-bindings/src/main/kotlin/uniffi/ (gitignored),
            // generated by
            //     `uniffi-bindgen generate --library <that .so> --language kotlin`.
            // AGP drops .so files from unit-test resources, so JNA gets the directory directly.
            it.systemProperty(
                "jna.library.path",
                rootProject.file("../../target/debug").absolutePath,
            )
        }
    }
}

dependencies {
    implementation("${libs.jna.get()}@aar")
    testImplementation(libs.jna)
    testImplementation(libs.junit)
    testImplementation(libs.json)
}
